package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadRight_TriageGen2Test {

    private StrBuilder strBuilder;

    @Before
    public void setUp() {
        strBuilder = new StrBuilder();
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthZero() {
        strBuilder.append("initial");
        strBuilder.appendFixedWidthPadRight("test", 0, ' ');
        assertEquals("initial", strBuilder.toString());
        assertEquals(7, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthNegative() {
        strBuilder.append("initial");
        strBuilder.appendFixedWidthPadRight("test", -5, ' ');
        assertEquals("initial", strBuilder.toString());
        assertEquals(7, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_NullObject_WithDefaultNullText() {
        // Default null text is usually "null"
        String nullText = strBuilder.getNullText();
        int expectedLen = nullText.length() + 10; // 10 is width
        strBuilder.appendFixedWidthPadRight(null, 10, '*');

        String expected = nullText + "******";
        assertEquals(expected, strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_NullObject_WithCustomNullText() {
        strBuilder.setNullText("N/A");
        strBuilder.appendFixedWidthPadRight(null, 5, '-');
        assertEquals("N/A--", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringShorterThanWidth() {
        strBuilder.appendFixedWidthPadRight("abc", 6, '.');
        assertEquals("abc...", strBuilder.toString());
        assertEquals(6, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringEqualWidth() {
        strBuilder.appendFixedWidthPadRight("abc", 3, '.');
        assertEquals("abc", strBuilder.toString());
        assertEquals(3, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringLongerThanWidth() {
        // The implementation uses str.getChars(0, width, buffer, size) 
        // which truncates the string to the width if strLen >= width
        strBuilder.appendFixedWidthPadRight("abcdef", 3, '.');
        assertEquals("abc", strBuilder.toString());
        assertEquals(3, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_IntegerObject() {
        strBuilder.appendFixedWidthPadRight(123, 5, '0');
        assertEquals("12300", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_Chaining() {
        strBuilder.appendFixedWidthPadRight("a", 3, '!')
                  .appendFixedWidthPadRight("b", 3, '?');
        assertEquals("a!!b??", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_LargeWidth() {
        strBuilder.appendFixedWidthPadRight("x", 20, '#');
        String result = strBuilder.toString();
        assertEquals(20, result.length());
        assertEquals('x', result.charAt(0));
        assertEquals('#', result.charAt(19));
    }
}
